import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class binarytrees {
    private static final int MIN_DEPTH = 4;

    static final class TreeNode {
        final TreeNode left;
        final TreeNode right;

        TreeNode(TreeNode left, TreeNode right) {
            this.left = left;
            this.right = right;
        }
    }

    private static TreeNode createTree(int depth) {
        if (depth == 0) {
            return new TreeNode(null, null);
        }
        return new TreeNode(createTree(depth - 1), createTree(depth - 1));
    }

    private static int checkTree(TreeNode node) {
        return node.left == null ? 1 : 1 + checkTree(node.left) + checkTree(node.right);
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        int n = args.length > 0 ? Integer.parseInt(args[0]) : 18;
        int maxDepth = Math.max(MIN_DEPTH + 2, n);
        int stretchDepth = maxDepth + 1;

        int stretchCheck = checkTree(createTree(stretchDepth));
        System.out.println("stretch tree of depth " + stretchDepth + "\t check: " + stretchCheck);

        TreeNode longLivedTree = createTree(maxDepth);

        int workers = Runtime.getRuntime().availableProcessors();
        ExecutorService executor = Executors.newFixedThreadPool(workers);

        int numDepths = (maxDepth - MIN_DEPTH) / 2 + 1;
        List<Future<Integer>>[] depthFutures = new List[numDepths];

        for (int d = MIN_DEPTH; d <= maxDepth; d += 2) {
            int depth = d;
            int depthIdx = (d - MIN_DEPTH) / 2;
            int iterations = 1 << (maxDepth - depth + MIN_DEPTH);
            int tasks = Math.min(iterations, workers * 2);

            depthFutures[depthIdx] = new ArrayList<>(tasks);
            for (int t = 0; t < tasks; t++) {
                int start = t * iterations / tasks;
                int end = (t + 1) * iterations / tasks;
                depthFutures[depthIdx].add(executor.submit(() -> {
                    int sum = 0;
                    for (int i = start; i < end; i++) {
                        sum += checkTree(createTree(depth));
                    }
                    return sum;
                }));
            }
        }

        for (int d = MIN_DEPTH; d <= maxDepth; d += 2) {
            int depthIdx = (d - MIN_DEPTH) / 2;
            int iterations = 1 << (maxDepth - d + MIN_DEPTH);
            int totalCheck = 0;
            for (Future<Integer> f : depthFutures[depthIdx]) {
                totalCheck += f.get();
            }
            System.out.println(iterations + "\t trees of depth " + d + "\t check: " + totalCheck);
        }

        executor.shutdown();

        int longLivedCheck = checkTree(longLivedTree);
        System.out.println("long lived tree of depth " + maxDepth + "\t check: " + longLivedCheck);
    }
}
