public class fannkuchredux {

    static void firstPermutation(int[] p, int[] pp, int[] count, int[] fact, int n, int idx) {
        for (int i = 0; i < n; ++i) {
            p[i] = i;
        }
        for (int i = n - 1; i > 0; --i) {
            int d = idx / fact[i];
            count[i] = d;
            idx %= fact[i];
