            }
        }
    }

    static class Worker extends Thread {
        final int n;
        final int totalPerms;
        final int chunkSize;
        final int[] fact;
        final AtomicInteger taskIndex;

        int maxFlips = 0;
        int checksum = 0;

        Worker(int n, int totalPerms, int chunkSize, int[] fact, AtomicInteger taskIndex) {
            this.n = n;
            this.totalPerms = totalPerms;
            this.chunkSize = chunkSize;
            this.fact = fact;
            this.taskIndex = taskIndex;
