            final int[] p = new int[n];
            final int[] pp = new int[n];
            final int[] count = new int[n];
            final int[] q = new int[n];

            int localMaxFlips = 0;
            int localChecksum = 0;

            while (true) {
                int start = taskIndex.getAndAdd(chunkSize);
                if (start >= totalPerms) break;
                int end = Math.min(start + chunkSize, totalPerms);

                firstPermutation(p, pp, count, fact, n, start);
                int sign = ((start & 1) == 0) ? 1 : -1;

                for (int cur = start; cur < end; cur++) {
                    int first = p[0];
                    if (first != 0) {
                        for (int i = 1; i < n; i++) {
                            q[i] = p[i];
                        }
                        int flips = 0;
                        do {
                            flips++;
                            int lo = 1, hi = first - 1;
                            while (lo < hi) {
                                int tmp = q[lo];
                                q[lo] = q[hi];
                                q[hi] = tmp;
                                lo++;
                                hi--;
                            }
                            int tmp = q[first];
                            q[first] = first;
                            first = tmp;
                        } while (first != 0);

                        localChecksum += sign * flips;
                        if (flips > localMaxFlips) {
                            localMaxFlips = flips;
                        }
                    }
                    sign = -sign;

                    if (cur + 1 < end) {
                        int temp = p[1];
                        p[1] = p[0];
                        p[0] = temp;

                        int i = 1;
                        while (++count[i] > i) {
                            count[i++] = 0;
                            int next = p[0];
                            for (int j = 0; j < i; ++j) {
                                p[j] = p[j + 1];
                            }
                            p[i] = next;
                        }
                    }
                }
            }

            this.maxFlips = localMaxFlips;
            this.checksum = localChecksum;
        }
    }

    public static void main(String[] args) {
