public class fasta {

    private static final int IM = 139968;
    private static final int IA = 3877;
    private static final int IC = 29573;
    private static int seed = 42;

    private static final int BUF_SIZE = 128 * 1024;
    private static final byte[] buf = new byte[BUF_SIZE];
    private static int bufPos = 0;
    private static final OutputStream out = System.out;

    private static final byte[] ALU = (
        "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
        "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
        "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
        "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
        "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA"
    ).getBytes(StandardCharsets.US_ASCII);

    private static final byte[] ALU_EXT = new byte[ALU.length + 60];
    static {
        System.arraycopy(ALU, 0, ALU_EXT, 0, ALU.length);
        System.arraycopy(ALU, 0, ALU_EXT, ALU.length, 60);
    }

    private static final char[] IUB_CHARS = {
        'a', 'c', 'g', 't',
        'B', 'D', 'H', 'K', 'M', 'N',
        'R', 'S', 'V', 'W', 'Y'
    };
    private static final double[] IUB_PROBS = {
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
        0.02, 0.02, 0.02, 0.02, 0.02
    };

    private static final char[] HOMO_CHARS = {
        'a', 'c', 'g', 't'
    };
    private static final double[] HOMO_PROBS = {
        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    };

    private static byte[] buildLookup(char[] symbols, double[] probs) {
        byte[] lookup = new byte[IM];
        double[] cum = new double[probs.length];
        double sum = 0.0;
        for (int i = 0; i < probs.length; i++) {
            sum += probs[i];
            cum[i] = sum;
        }
        cum[cum.length - 1] = 1.0;

        for (int s = 0; s < IM; s++) {
            double r = (double) s / (double) IM;
            for (int i = 0; i < cum.length; i++) {
                if (cum[i] > r) {
                    lookup[s] = (byte) symbols[i];
                    break;
                }
            }
        }
        return lookup;
    }

    private static void writeBytes(byte[] b) throws IOException {
        int offset = 0;
        int len = b.length;
        while (len > 0) {
            if (bufPos == BUF_SIZE) {
                out.write(buf, 0, bufPos);
                bufPos = 0;
            }
            int toCopy = Math.min(len, BUF_SIZE - bufPos);
            System.arraycopy(b, offset, buf, bufPos, toCopy);
            bufPos += toCopy;
            offset += toCopy;
            len -= toCopy;
        }
    }

    private static void makeRepeatFasta(int n) throws IOException {
        int bytesRemaining = 2 * n;
        int aluPos = 0;
        while (bytesRemaining > 0) {
            int lineLen = Math.min(60, bytesRemaining);
            if (bufPos + lineLen + 1 > BUF_SIZE) {
                out.write(buf, 0, bufPos);
                bufPos = 0;
            }
            System.arraycopy(ALU_EXT, aluPos, buf, bufPos, lineLen);
            bufPos += lineLen;
            buf[bufPos++] = '\n';
            aluPos += lineLen;
            if (aluPos >= ALU.length) {
                aluPos -= ALU.length;
            }
            bytesRemaining -= lineLen;
        }
    }

    private static void makeRandomFasta(byte[] lookup, int n) throws IOException {
        int bytesRemaining = n;
        int s = seed;
        while (bytesRemaining >= 60) {
            if (bufPos + 61 > BUF_SIZE) {
                out.write(buf, 0, bufPos);
                bufPos = 0;
            }
            for (int i = 0; i < 60; i++) {
                s = (s * IA + IC) % IM;
                buf[bufPos + i] = lookup[s];
            }
            bufPos += 60;
            buf[bufPos++] = '\n';
            bytesRemaining -= 60;
        }
        if (bytesRemaining > 0) {
            if (bufPos + bytesRemaining + 1 > BUF_SIZE) {
                out.write(buf, 0, bufPos);
                bufPos = 0;
            }
            for (int i = 0; i < bytesRemaining; i++) {
                s = (s * IA + IC) % IM;
                buf[bufPos + i] = lookup[s];
            }
            bufPos += bytesRemaining;
            buf[bufPos++] = '\n';
        }
        seed = s;
    }

    public static void main(String[] args) throws IOException {
        int n = 12000000;
        if (args.length > 0) {
            n = Integer.parseInt(args[0]);
        }

        byte[] iubLookup = buildLookup(IUB_CHARS, IUB_PROBS);
        byte[] homoLookup = buildLookup(HOMO_CHARS, HOMO_PROBS);

        writeBytes(">ONE Homo sapiens alu\n".getBytes(StandardCharsets.US_ASCII));
        makeRepeatFasta(n);

        writeBytes(">TWO IUB ambiguity codes\n".getBytes(StandardCharsets.US_ASCII));
        makeRandomFasta(iubLookup, 3 * n);

        writeBytes(">THREE Homo sapiens frequency\n".getBytes(StandardCharsets.US_ASCII));
        makeRandomFasta(homoLookup, 5 * n);

        if (bufPos > 0) {
            out.write(buf, 0, bufPos);
            bufPos = 0;
        }
        out.flush();
    }
}
