import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class knucleotide {

    static final byte[] CODE = new byte[256];
    static final char[] DECODE = {'A', 'C', 'T', 'G'};

    static {
        Arrays.fill(CODE, (byte) -1);
        CODE['A'] = CODE['a'] = 0;
        CODE['C'] = CODE['c'] = 1;
        CODE['T'] = CODE['t'] = 2;
        CODE['G'] = CODE['g'] = 3;
    }

    static class Entry implements Comparable<Entry> {
        final String key;
        final int count;

        Entry(String key, int count) {
            this.key = key;
            this.count = count;
        }

        @Override
        public int compareTo(Entry o) {
            if (o.count != this.count) {
                return Integer.compare(o.count, this.count);
            }
            return this.key.compareTo(o.key);
        }
    }

    static class LongIntTable {
        final long[] keys;
        final int[] vals;
        final int mask;
        final int shift;

        LongIntTable(int capacity) {
            keys = new long[capacity];
            vals = new int[capacity];
            Arrays.fill(keys, -1L);
            mask = capacity - 1;
            shift = 64 - Integer.numberOfTrailingZeros(capacity);
        }

        void putOrIncrement(long key) {
            int slot = (int) ((key * 0x9E3779B97F4A7C15L) >>> shift);
            while (true) {
                long k = keys[slot];
                if (k == key) {
                    vals[slot]++;
                    return;
                }
                if (k == -1L) {
                    keys[slot] = key;
                    vals[slot] = 1;
                    return;
                }
                slot = (slot + 1) & mask;
            }
        }

        int get(long key) {
            int slot = (int) ((key * 0x9E3779B97F4A7C15L) >>> shift);
            while (true) {
                long k = keys[slot];
                if (k == key) {
                    return vals[slot];
                }
                if (k == -1L) {
                    return 0;
                }
                slot = (slot + 1) & mask;
            }
        }

        List<Entry> getEntries(int k) {
            List<Entry> list = new ArrayList<>();
            for (int i = 0; i < keys.length; i++) {
                if (keys[i] != -1L) {
                    list.add(new Entry(decode(keys[i], k), vals[i]));
                }
            }
            return list;
        }
    }

    static long encode(String s) {
        long key = 0;
        for (int i = 0; i < s.length(); i++) {
            key = (key << 2) | CODE[s.charAt(i)];
        }
        return key;
    }

    static String decode(long key, int k) {
        char[] chars = new char[k];
        for (int i = k - 1; i >= 0; i--) {
            chars[i] = DECODE[(int) (key & 3)];
            key >>>= 2;
        }
        return new String(chars);
    }

    static int tableCapacity(int seqLen, int k) {
        long maxPossible = Math.max(1, Math.min((long) seqLen - k + 1, 1L << (2 * k)));
        int cap = 16;
        while (cap < maxPossible * 1.35 && cap < (1 << 25)) {
            cap <<= 1;
        }
        return cap;
    }

    static void count(byte[] seq, int seqLen, int k, LongIntTable table) {
        if (seqLen < k) return;
        long mask = (1L << (2 * k)) - 1;
        long key = 0;
        for (int i = 0; i < k - 1; i++) {
            key = (key << 2) | seq[i];
        }
        for (int i = k - 1; i < seqLen; i++) {
            key = ((key << 2) & mask) | seq[i];
            table.putOrIncrement(key);
        }
    }

    static String formatFrequencies(byte[] seq, int seqLen, int k) {
        int cap = tableCapacity(seqLen, k);
        LongIntTable table = new LongIntTable(cap);
        count(seq, seqLen, k, table);
        List<Entry> entries = table.getEntries(k);
        Collections.sort(entries);
        int total = Math.max(1, seqLen - k + 1);
        StringBuilder sb = new StringBuilder();
        for (Entry e : entries) {
            sb.append(String.format(Locale.US, "%s %.3f\n", e.key, (e.count * 100.0) / total));
        }
        return sb.toString();
    }

    static String formatCount(byte[] seq, int seqLen, String fragment) {
        int k = fragment.length();
        int cap = tableCapacity(seqLen, k);
        LongIntTable table = new LongIntTable(cap);
        count(seq, seqLen, k, table);
        long key = encode(fragment);
        int cnt = table.get(key);
        return cnt + "\t" + fragment;
    }

    static byte[] readSequence(InputStream in) throws IOException {
        byte[] buf = new byte[1024 * 1024];
