public class mandelbrot {
    public static void main(String[] args) throws Exception {
        int n = 3504;
        if (args.length > 0) {
            n = Integer.parseInt(args[0]);
        }

        int bytesPerRow = (n + 7) / 8;
        byte[] out = new byte[n * bytesPerRow];

        double[] crb = new double[n];
        double[] cib = new double[n];
        for (int i = 0; i < n; i++) {
            crb[i] = 2.0 * i / n - 1.5;
            cib[i] = 2.0 * i / n - 1.0;
        }

        int numThreads = Runtime.getRuntime().availableProcessors();
        Thread[] threads = new Thread[numThreads];
        AtomicInteger nextRow = new AtomicInteger(0);
        final int N = n;
        final int CHUNK_SIZE = 16;

        for (int t = 0; t < numThreads; t++) {
            threads[t] = new Thread(() -> {
                int yStart;
                while ((yStart = nextRow.getAndAdd(CHUNK_SIZE)) < N) {
                    int yEnd = Math.min(yStart + CHUNK_SIZE, N);
                    for (int y = yStart; y < yEnd; y++) {
                        double cib_y = cib[y];
                        int byteCount = y * bytesPerRow;
                        int bitNum = 0;
                        int byteAcc = 0;

                        for (int x = 0; x < N; x++) {
                            double cr = crb[x];
                            double zr = 0.0;
                            double zi = 0.0;
                            double tr = 0.0;
                            double ti = 0.0;

                            int i = 50;
                            do {
                                zi = 2.0 * zr * zi + cib_y;
                                zr = tr - ti + cr;
                                tr = zr * zr;
                                ti = zi * zi;
                            } while (tr + ti <= 4.0 && --i > 0);

                            byteAcc = (byteAcc << 1) | (i == 0 ? 1 : 0);
                            bitNum++;

                            if (bitNum == 8) {
                                out[byteCount++] = (byte) byteAcc;
                                bitNum = 0;
                                byteAcc = 0;
                            }
                        }

                        if (bitNum != 0) {
                            byteAcc <<= (8 - bitNum);
                            out[byteCount] = (byte) byteAcc;
                        }
                    }
                }
            });
            threads[t].start();
        }

        for (Thread t : threads) {
            t.join();
