        while (count < n) {
            BigInteger q3 = q.shiftLeft(1).add(q);
            BigInteger u = q3.add(r);
            BigInteger[] dr = u.divideAndRemainder(t);
            BigInteger d = dr[0];
            BigInteger rem = dr[1];

            if (rem.add(q).compareTo(t) < 0) {
                line.append(d.intValue());
                count++;

                if (count % 10 == 0) {
                    line.append('\t').append(':').append(count).append('\n');
                    System.out.print(line);
                    line.setLength(0);
                }

                r = rem.subtract(q3).multiply(BigInteger.TEN);
                q = q.multiply(BigInteger.TEN);
            } else {
                long k2 = (k << 1) + 1;
                BigInteger bigK2 = BigInteger.valueOf(k2);
                BigInteger bigK = BigInteger.valueOf(k);

                r = q.shiftLeft(1).add(r).multiply(bigK2);
                t = t.multiply(bigK2);
                q = q.multiply(bigK);
