            size += read;
        }

        byte[] out = new byte[65536];
        int i = 0;
        while (i < size) {
            if (in[i] == '>') {
                int headerStart = i;
                while (i < size && in[i] != '\n') {
                    i++;
                }
                if (i < size && in[i] == '\n') {
                    i++;
                }
