import java.util.Arrays;
import java.util.Locale;
import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;

public class spectralnorm {

    private static double evalA(int i, int j) {
        return 1.0 / (((i + j) * (i + j + 1) >> 1) + i + 1);
    }

    public static void main(String[] args) {
        int n = 4000;
        if (args.length > 0) {
            n = Integer.parseInt(args[0]);
        }

        double[] u = new double[n];
        double[] v = new double[n];
        double[] tmp = new double[n];
        Arrays.fill(u, 1.0);

        int numThreads = Runtime.getRuntime().availableProcessors();
        Thread[] threads = new Thread[numThreads];
        int chunk = (n + numThreads - 1) / numThreads;

        CyclicBarrier barrier = new CyclicBarrier(numThreads);

        final int finalN = n;
        for (int t = 0; t < numThreads; t++) {
            final int start = t * chunk;
            final int end = Math.min(start + chunk, finalN);

            threads[t] = new Thread(() -> {
                try {
                    for (int it = 0; it < 10; it++) {
                        // MultiplyAtAv(u, v):
                        // 1. tmp = A * u
                        multiplyAv(u, tmp, start, end, finalN);
                        barrier.await();

                        // 2. v = A^T * tmp
                        multiplyAtv(tmp, v, start, end, finalN);
                        barrier.await();

                        // MultiplyAtAv(v, u):
                        // 3. tmp = A * v
                        multiplyAv(v, tmp, start, end, finalN);
                        barrier.await();

                        // 4. u = A^T * tmp
                        multiplyAtv(tmp, u, start, end, finalN);
                        barrier.await();
                    }
                } catch (InterruptedException | BrokenBarrierException e) {
                    Thread.currentThread().interrupt();
                }
            });
            threads[t].start();
        }

        for (Thread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        double vBv = 0.0;
        double vv = 0.0;
        for (int i = 0; i < n; i++) {
            vBv += u[i] * v[i];
            vv += v[i] * v[i];
        }

        System.out.printf(Locale.US, "%.9f\n", Math.sqrt(vBv / vv));
    }

    private static void multiplyAv(double[] src, double[] dst, int start, int end, int n) {
        for (int i = start; i < end; i++) {
            double sum = 0.0;
            for (int j = 0; j < n; j++) {
                sum += src[j] * evalA(i, j);
            }
            dst[i] = sum;
        }
    }

    private static void multiplyAtv(double[] src, double[] dst, int start, int end, int n) {
        for (int i = start; i < end; i++) {
            double sum = 0.0;
            for (int j = 0; j < n; j++) {
                sum += src[j] * evalA(j, i);
            }
            dst[i] = sum;
        }
    }
}
